        message = message + "<p>NCR QTY% is " + vendorDetails.filter((i) => i.plantCode == data)[0].ncrPercentage + " (0% is the number we want to see)  </p>";
        message = message + "<p>Lead Time Accuracy% is " + vendorDetails.filter((i) => i.plantCode == data)[0].ltaPercentage + " (Above 95% is favorable) </p>";
