        _angular_core__WEBPACK_IMPORTED_MODULE_0__["ɵɵtext"](416, " To use the ScoreUs system effectively, you must maintain five raw data tables, which should be available from your current ERP or purchasing system. These tables are essential for generating accurate performance reports. Please ensure the data is properly formatted according to the provided templates: ");
        _angular_core__WEBPACK_IMPORTED_MODULE_0__["ɵɵelementEnd"]();
        _angular_core__WEBPACK_IMPORTED_MODULE_0__["ɵɵelement"](417, "hr", 10);
